BEGIN;
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_target_type_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_type_check CHECK (type IN ('ORDER_UPDATE', 'WITHDRAWAL_APPROVED', 'WITHDRAWAL_REJECTED', 'WALLET_EVENT', 'TERM_EXPIRY', 'VERIFICATION_RESULT', 'QUEUE_TASK', 'DONATION_RECORDED', 'DONATION_HANDED_OVER', 'COMMENT_REPLIED', 'POST_COMMENTED', 'FOLLOWED_ORG_CAMPAIGN', 'FOLLOWED_ORG_POST', 'VIOLATION_WARNING', 'VIOLATION_REPORT_HANDLED'));
ALTER TABLE notifications ADD CONSTRAINT notifications_target_type_check CHECK (target_type IN ('CAMPAIGN', 'POST', 'ORGANIZATION', 'LEGAL_CHANGE', 'DEGRADED_ITEM_CASE', 'WITHDRAWAL', 'PRODUCT'));
COMMIT;
